import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"
import { Slot } from "radix-ui"

// Deshabilitado: todos los botones llenos (principal, gris, blanco y rojos) quedan iguales,
// fondo gris y texto gris, no el color de cada uno a media luz. Los de borde y los de texto se aclaran.
const FILLED_OFF = "disabled:bg-secondary disabled:text-muted-foreground disabled:opacity-100"

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center rounded-full border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3",
  {
    variants: {
      variant: {
        default: `bg-primary text-primary-foreground hover:bg-brand-hover ${FILLED_OFF}`,
        outline:
          "border-input bg-transparent hover:border-brand hover:text-brand aria-expanded:border-brand aria-expanded:text-brand dark:border-input",
        secondary:
          `bg-secondary text-secondary-foreground hover:bg-brand hover:text-brand-foreground active:bg-brand-strong active:text-brand-foreground aria-expanded:bg-brand aria-expanded:text-brand-foreground ${FILLED_OFF}`,
        // Relleno blanco (en modo oscuro, del color de las cajas). Ej: flechas para cambiar de mes
        card: `bg-card text-foreground hover:bg-brand hover:text-brand-foreground active:bg-brand-strong active:text-brand-foreground ${FILLED_OFF}`,
        ghost:
          "hover:bg-card-hover hover:text-foreground aria-expanded:bg-card-hover aria-expanded:text-foreground",
        destructive:
          `bg-destructive text-destructive-foreground hover:bg-destructive-hover focus-visible:border-destructive/40 focus-visible:ring-destructive/30 ${FILLED_OFF}`,
        // Botón de solo texto: siempre subrayado y siempre del tamaño normal (14px), nunca chico
        link: "text-brand-text underline underline-offset-4 hover:decoration-2",
        // Lo mismo pero en rojo, para cancelar o borrar sin que grite. Ej: cancelar la carga por voz
        "destructive-link": "text-destructive underline underline-offset-4 hover:decoration-2",
        // Borrar algo sin que grite: borde gris (el mismo que "Con borde") y texto rojo, se llena de rojo al pasar el mouse
        "destructive-outline":
          "border-input bg-transparent text-destructive hover:border-destructive hover:bg-destructive hover:text-destructive-foreground",
        // Cancelar/borrar suave: fondo gris y texto rojo (diseño outfit)
        "destructive-soft":
          `bg-secondary text-destructive hover:bg-destructive hover:text-destructive-foreground ${FILLED_OFF}`,
        // Agregar algo nuevo: borde punteado y texto gris
        dashed:
          "border-dashed border-input bg-transparent text-muted-foreground hover:border-brand hover:text-brand",
      },
      size: {
        default:
          "h-10 gap-1.5 px-4 has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3",
        sm: "h-8 gap-1 rounded-full px-3 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        icon: "size-10",
        "icon-xs":
          "size-6 rounded-full in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-7 rounded-full in-data-[slot=button-group]:rounded-lg",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }
